function bestAverage(nums: number[], k: number): number {
  let best = -Infinity;
  for (let s = 0; s + k <= nums.length; s++) {
    let sum = 0;
    for (let i = s; i < s + k; i++) sum += nums[i];
    best = Math.max(best, sum);
  }
  return best / k;
}

